import sys
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    n, order = int(parts[0]), parts[1]
    words = lines[1:1+n]
    rank = {c: i for i, c in enumerate(order)}
    def is_less(w1, w2):
        for c1, c2 in zip(w1, w2):
            if c1 != c2: return rank[c1] < rank[c2]
        return len(w1) <= len(w2)
    ok = all(is_less(words[i], words[i+1]) for i in range(len(words)-1))
    print('true' if ok else 'false')
